import {uid,clone,ROLES,hierarchy,makeDemo,validateState,assignTask,moveMember,removeMember,workload,exportState,MAX_MEMBERS,primaryOwner,ownerRole,unitPath,removeUnit,mergeWorkspace} from './model.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={logo:'M3 17V5l9 8 9-8v12',org:'M12 3v5M5 15v-4h14v4M12 11v4M8 3h8v5H8zM2 15h6v6H2zM9 15h6v6H9zM16 15h6v6h-6z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',table:'M3 4h18v16H3zM3 9h18M9 9v11',history:'M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8M17 4a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',task:'M9 5H4v16h16V5h-5M9 3h6v4H9zM8 12h8M8 16h5',share:'M9 7l6-3M9 9l6 7M3 8a3 3 0 1 0 6 0 3 3 0 0 0-6 0M15 4a3 3 0 1 0 6 0 3 3 0 0 0-6 0M15 18a3 3 0 1 0 6 0 3 3 0 0 0-6 0',inbox:'M3 4h18v15H3zM3 13h5l2 3h4l2-3h5',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6zM17 11h1',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',cloud:'M7 18H5a4 4 0 0 1-1-8 7 7 0 0 1 13-3 5 5 0 0 1 2 10M9 16l3 3 5-6',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M9 9a3 3 0 1 1 4 3v2M12 17h.01',grip:'M8 5h.01M16 5h.01M8 12h.01M16 12h.01M8 19h.01M16 19h.01',edit:'m14 5 5 5M4 16 16 4a2 2 0 0 1 4 4L8 20H4z',close:'M6 6l12 12M6 18 12-12',fit:'M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6',undo:'M4 10h10a6 6 0 0 1 0 12M4 10l5-5M4 10l5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',arrow:'M5 12h14m-5-5 5 5-5 5',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 11v6M12 7h.01',leaf:'M19 3C6 2 3 7 5 15s15 7 14-12ZM7 17l8-9',copy:'M8 8h13v13H8zM16 8V3H3v13h5',folder:'M3 6h7l2 3h9v12H3z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.task}"/></svg>`;
const KEY='maha-rolemap:v1', BACKUP='maha-rolemap:recovery', VIEW_KEY='maha-rolemap:show-org-tasks';
let showOrgTasks=true;
try {showOrgTasks=localStorage.getItem(VIEW_KEY)!=='false';}catch{}
let state,storageOK=true,loadWarning='';
try {const saved=localStorage.getItem(KEY);state=saved?validateState(JSON.parse(saved)):makeDemo();}catch(e){state=makeDemo();loadWarning='저장된 데이터를 읽지 못했습니다. 원본은 그대로 두었습니다. JSON 백업을 불러와 복구할 수 있습니다.';storageOK=false;}
let view='org',taskFilter='unassigned',search='',globalSearch='',category='',dropMode='move',zoom=1,autoFit=true,undo=[],redo=[],drag=null,modalFocus=null,printMode='table';
let orgLayout='auto',unitFilter='',inboxOpen=false;
const dept=()=>state.departments.find(d=>d.id===state.activeDepartmentId)||state.departments[0];
const initials=n=>n.slice(-2);
const avatar=m=>`<span class="avatar c${Number(m.color)%6||0}">${esc(initials(m.name))}</span>`;
const taskCount=m=>dept().tasks.filter(t=>t.owners.includes(m.id)).length;
function toast(msg,error=false){const e=document.createElement('div');e.className=`toast${error?' error':''}`;e.textContent=msg;$('#toasts').append(e);setTimeout(()=>e.remove(),4500);}
function save(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('브라우저 저장 공간을 사용할 수 없습니다. JSON 파일로 저장해 주세요.',true);}}
function change(label,fn){const before=clone(state);try{fn();validateState(state);undo.push(before);if(undo.length>40)undo.shift();redo=[];state.history.unshift({at:new Date().toISOString(),text:label});state.history=state.history.slice(0,100);save();render();}catch(e){state=before;throw e;}}
function rewind(forward=false){const from=forward?redo:undo,to=forward?undo:redo;if(!from.length)return;to.push(clone(state));state=from.pop();save();render();toast(forward?'다시 실행했습니다.':'마지막 변경을 되돌렸습니다.');}
function hit(t){const q=(search||globalSearch).toLowerCase();return (!q||[t.title,t.code,t.category,t.notes,...t.owners.map(id=>dept().members.find(m=>m.id===id)?.name||'')].join(' ').toLowerCase().includes(q))&&(!category||t.category===category);}
function filteredTasks(){return dept().tasks.filter(t=>hit(t)&&(taskFilter==='all'||taskFilter==='unassigned'&&!t.owners.length||taskFilter==='shared'&&t.owners.length>1));}
function personCard(m,depth){
 const ts=dept().tasks.filter(t=>t.owners.includes(m.id));
 const highlighted=globalSearch&&([m.name,m.role,m.team,...ts.map(t=>t.title)].join(' ').toLowerCase().includes(globalSearch.toLowerCase()));
 const tasks=showOrgTasks?`<div class="person-task-list" aria-label="${esc(m.name)} 담당 업무">${ts.map(t=>{
  const primary=primaryOwner(t)===m.id,shared=t.owners.length>1;
  return `<button class="org-task ${shared?'shared':''}" type="button" draggable="true" data-drag-task="${esc(t.id)}" data-action="task-edit" data-id="${esc(t.id)}" aria-label="${esc(t.title)}, ${ownerRole(t,m.id)}, 업무 편집"><span class="org-task-line"><span class="org-task-code">${esc(t.code||'·')}</span><span class="org-task-title">${esc(t.title)}</span></span><span class="org-task-role">${ownerRole(t,m.id)}${shared?' · 공동 '+t.owners.length+'명':''}</span>${t.notes?`<span class="org-task-note">${esc(t.notes)}</span>`:''}</button>`;
 }).join('')||'<p class="org-no-tasks">아직 배정된 업무가 없어요.</p>'}</div>`:'';
 return `<article class="person-card ${showOrgTasks?'tasks-expanded':''} ${m.role==='처장'?'leader':m.role==='부처장'?'deputy':''} ${highlighted?'highlight':''}" data-depth="${depth}" data-action="person" data-id="${esc(m.id)}" data-drop-person="${esc(m.id)}"><div class="person-top"><button type="button" class="person-profile" aria-label="${esc(m.name)} ${esc(m.role)}, 담당 업무 ${ts.length}건. 상세 보기" data-action="person" data-id="${esc(m.id)}">${avatar(m)}<span><span class="person-name">${esc(m.name)}${m.employment?`<small class="employment-tag">${esc(m.employment)}</small>`:''}</span><span class="person-role">${esc([m.role,m.grade].filter(Boolean).join(' · '))}${(m.unitId||m.team)?' · '+esc(m.unitId?unitPath(dept(),m.unitId):m.team):''}</span></span></button><button class="grip" title="끌어서 보고 대상 변경" aria-label="${esc(m.name)} 보고 대상 변경" draggable="true" data-drag-member="${esc(m.id)}" data-action="member-edit" data-id="${esc(m.id)}">${icon('grip')}</button></div>${tasks}<div class="person-bottom"><strong>${ts.length?'업무 '+ts.length+'건':'업무 미배정'}</strong><span class="task-dots" aria-hidden="true">${ts.slice(0,7).map(t=>`<i class="${t.owners.length>1?'shared':''}"></i>`).join('')}</span></div></article>`;
}
function treeNodes(parent=null,depth=0){return dept().members.filter(m=>m.parentId===parent).map(m=>`<li>${personCard(m,depth)}${dept().members.some(c=>c.parentId===m.id)?`<ul>${treeNodes(m.id,depth+1)}</ul>`:''}</li>`).join('');}
function taskCard(t){const names=t.owners.map(id=>dept().members.find(m=>m.id===id)?.name).filter(Boolean);return `<div class="task-card" draggable="true" data-drag-task="${esc(t.id)}" data-action="task-edit" data-id="${esc(t.id)}" tabindex="0" role="button" aria-label="${esc(t.title)}, ${names.length?esc(names.join(', ')):'미배정'}"><div class="task-card-top"><span class="task-code">${esc(t.code||'·')}</span><b>${esc(t.title)}</b><span class="grip">${icon('grip')}</span></div><div class="task-meta"><span>${esc(t.category||'일반')}</span><span class="${names.length>1?'shared-tag':''}">${names.length>1?'공동 '+names.length+'명':names.length?esc(names[0]):'미배정'}${t.priority==='높음'?' · 중요':''}</span></div></div>`;}
function taskPanel(){const count=dept().tasks.filter(t=>!t.owners.length).length;return `<aside class="task-panel"><div class="panel-head"><div class="panel-title"><span>${icon('task')}업무 보관함</span><button class="icon-button" data-action="task-new" aria-label="업무 추가">${icon('plus')}</button></div><p>업무를 구성원 카드 위로 끌어다 놓으세요.<br>클릭하면 담당자를 직접 선택할 수도 있어요.</p><div class="search">${icon('search')}<input id="task-search" value="${esc(search)}" placeholder="업무명, 담당자 검색" aria-label="업무 보관함 검색"></div><div class="filter-tabs"><button class="${taskFilter==='unassigned'?'active':''}" data-action="task-filter" data-value="unassigned">미배정 <span class="pill">${count}</span></button><button class="${taskFilter==='shared'?'active':''}" data-action="task-filter" data-value="shared">공동 담당</button><button class="${taskFilter==='all'?'active':''}" data-action="task-filter" data-value="all">전체</button></div></div><div class="task-list unassign-drop" data-drop-unassign="true">${filteredTasks().map(taskCard).join('')||`<div class="empty">${icon('check')}<strong>${taskFilter==='unassigned'?'모든 업무에 담당자가 있어요':'조건에 맞는 업무가 없어요'}</strong><p>다른 조건을 선택하거나<br>새로운 업무를 추가해 보세요.</p></div>`}</div><div class="panel-footer"><div class="mode-label">업무를 놓을 때</div><div class="segmented"><button data-action="drop-mode" data-value="move" class="${dropMode==='move'?'active':''}" title="기존 담당자를 대신하여 한 사람에게 배정">담당 이동</button><button data-action="drop-mode" data-value="share" class="${dropMode==='share'?'active':''}" title="기존 담당자를 유지하고 협업 담당으로 추가">공동 담당 추가</button></div></div></aside>`;}
function orgView(){
 const d=dept(),hasUnits=!!d.units?.length,grouped=orgLayout==='units'||orgLayout==='auto'&&hasUnits;
 return `<div class="workspace-body ${grouped?'grouped-workspace':''}"><section class="canvas-area"><div class="canvas-toolbar"><div class="canvas-title">${esc(d.name)} <small>${d.members.length}명의 구성원</small><button class="icon-button" data-action="dept-edit" aria-label="부서 정보 수정">${icon('edit')}</button></div><div class="canvas-options"><select id="org-layout" aria-label="조직도 배치"><option value="units" ${grouped?'selected':''}>팀·파트별 보기</option><option value="hierarchy" ${!grouped?'selected':''}>보고 관계 보기</option></select><button class="btn" data-action="units-manage">${icon('org')}팀·파트 관리</button><button type="button" id="org-tasks-toggle" class="display-toggle" role="switch" aria-checked="${showOrgTasks}" aria-label="업무내용 표시" aria-controls="organization-tree" data-action="toggle-org-tasks"><span class="toggle-track" aria-hidden="true"><span></span></span><span>업무내용 표시</span><small>${showOrgTasks?'켜짐':'꺼짐'}</small></button>${grouped?`<button class="btn" data-action="toggle-inbox">${icon('inbox')}보관함 ${inboxOpen?'접기':'열기'}</button>`:''}</div></div>${grouped?unitView():`<div class="graph-viewport"><div class="root-drop" data-drop-root="true">이곳에 놓으면 최상위 구성원으로 이동합니다</div><div class="graph-shell"><div class="tree ${showOrgTasks?'tasks-visible':''}" id="organization-tree"><ul>${treeNodes()}</ul></div></div>${!d.members.length?'<div class="empty">구성원을 추가해 조직도를 시작하세요.</div>':''}</div><div class="canvas-bottom"><span>${showOrgTasks?'업무를 누르면 편집 · 이름을 누르면 구성원 상세':'업무내용 표시를 켜면 담당 업무를 모두 볼 수 있어요'}</span><div class="zoom"><button data-action="zoom-out" aria-label="축소">−</button><span id="zoom-label">100%</span><button data-action="zoom-in" aria-label="확대">+</button><button class="fit" data-action="zoom-fit">${icon('fit')}맞춤</button></div></div>`}</section>${!grouped||inboxOpen?taskPanel():''}</div>`;
}
function tableView(){const d=dept(),max=Math.max(1,...d.members.map(m=>workload(d,m.id)));const ms=d.members.filter(m=>!globalSearch||[m.name,m.role,m.team,...d.tasks.filter(t=>t.owners.includes(m.id)).map(t=>t.title)].join(' ').toLowerCase().includes(globalSearch.toLowerCase()));return `<div class="workspace-body"><div class="table-view"><div class="info-box">업무량은 난이도 점수(1~3)를 담당 인원으로 나누어 합산합니다. 실제 근무시간이나 성과 평가를 의미하지 않습니다.</div><table class="data-table"><thead><tr><th>구성원 / 직책</th><th>주담당 업무</th><th>협업·공동 담당 업무</th><th>배정 현황</th><th></th></tr></thead><tbody>${ms.map(m=>{const main=d.tasks.filter(t=>primaryOwner(t)===m.id),shared=d.tasks.filter(t=>t.owners.includes(m.id)&&primaryOwner(t)!==m.id),w=workload(d,m.id);return `<tr><td><button class="inline-person" data-action="person" data-id="${esc(m.id)}">${avatar(m)}<span>${esc(m.name)}<small>${esc([m.role,m.grade].filter(Boolean).join(' · '))}${(m.unitId||m.team)?' · '+esc(m.unitId?unitPath(dept(),m.unitId):m.team):''}</small></span></button></td><td>${main.map(t=>`<button class="tag ${t.owners.length>1?'shared':''}" data-action="task-edit" data-id="${esc(t.id)}">${esc(t.code)} ${esc(t.title)}</button>`).join('')||'—'}</td><td>${shared.map(t=>`<button class="tag shared" data-action="task-edit" data-id="${esc(t.id)}">${esc(t.code)} ${esc(t.title)}</button>`).join('')||'—'}</td><td>${main.length+shared.length}건<div class="loadbar"><i style="width:${w/max*100}%"></i></div><small title="업무별 난이도(1~3) ÷ 담당 인원 수의 합계입니다. 성과 평가 점수가 아닙니다.">참고 업무량 ${w.toFixed(1)}점</small></td><td><button class="icon-button" data-action="member-edit" data-id="${esc(m.id)}" aria-label="${esc(m.name)} 수정">${icon('edit')}</button></td></tr>`;}).join('')}</tbody></table>${!ms.length?'<div class="empty">구성원이 없거나 검색 결과가 없습니다.</div>':''}</div></div>`;}
function boardView(){return `<div class="board-filters"><div class="filter-tabs" style="margin:0">${[['all','전체 업무'],['unassigned','미배정'],['shared','공동 담당']].map(([v,l])=>`<button class="${taskFilter===v?'active':''}" data-action="task-filter" data-value="${v}">${l}</button>`).join('')}</div><select id="category-filter" aria-label="업무 분류"><option value="">모든 분류</option>${[...new Set(dept().tasks.map(t=>t.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn ghost" style="margin-left:auto" data-action="task-new">${icon('plus')} 업무 추가</button></div><div class="workspace-body"><div class="task-grid">${filteredTasks().map(taskCard).join('')||'<div class="empty">조건에 맞는 업무가 없습니다.</div>'}</div></div>`;}
function historyView(){return `<div class="workspace-body"><div class="table-view"><div class="info-box">최근 100건의 변경을 기록합니다. 실행 취소는 현재 창에서 작업한 최근 40단계까지 가능합니다. JSON 저장 시 변경 기록도 함께 포함됩니다.</div>${state.history.map(h=>`<div class="history-row"><small>${esc(new Date(h.at).toLocaleString('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}))}</small><span>${esc(h.text)}</span></div>`).join('')||'<div class="empty">아직 변경 기록이 없습니다. 조직도를 편집해 보세요.</div>'}</div></div>`;}
function render(){const d=dept(),un=d.tasks.filter(t=>!t.owners.length).length,shared=d.tasks.filter(t=>t.owners.length>1).length;$('#app').innerHTML=`<aside class="sidebar"><div class="mach-home-nav" data-html2canvas-ignore="true">
  <a class="mach-home-link" href="https://erakeun.github.io/ERICAAI/" aria-label="MACH 홈으로 이동">
    <img src="assets/mach-three-speed-lines.png" alt="MACH" decoding="async">
  </a>
</div><div class="workspace-label">WORKSPACE</div>${[['org','org','업무분장'],['board','task','전체 업무'],['table','table','담당자별 현황'],['history','history','변경 기록']].map(([v,i,l])=>`<button class="nav-item ${view===v?'active':''}" data-action="view" data-value="${v}" title="${l}">${icon(i)}<span>${l}</span>${v==='board'?`<span class="pill">${d.tasks.length}</span>`:''}</button>`).join('')}<div class="side-divider"></div><div class="dept-section"><div class="workspace-label">MY DEPARTMENTS</div>${state.departments.map(x=>`<button class="dept-row ${x.id===d.id?'active':''}" data-action="dept-switch" data-id="${esc(x.id)}"><span class="dot"></span>${esc(x.name)}<span class="small-count">${x.members.length}</span></button>`).join('')}<button class="nav-item" data-action="dept-new">${icon('plus')}<span>부서 추가</span></button></div><div class="side-note">${icon('leaf')}<strong>명확한 역할, 더 나은 협업</strong>작은 업무도 놓치지 않도록.<br>우리 팀의 일하는 방식을 그려요.<button class="btn ghost" style="padding:9px 0 0;font-size:10px" data-action="help">사용 가이드 ${icon('arrow')}</button></div><div class="profile"><span class="top-avatar">M</span><span><b>우리 팀 워크스페이스</b><span style="color:#9ba68f">브라우저에 저장되는 개인 작업</span></span></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span class="mobile-brand">MACH</span><span>워크스페이스</span>${icon('chevron')}<b>업무분장 스튜디오</b></div><div class="top-actions"><span class="saved">${icon(storageOK?'check':'info')}${storageOK?'이 브라우저에 자동 저장':'JSON 저장이 필요해요'}</span><button class="icon-button" data-action="help" aria-label="사용 가이드">${icon('help')}</button><div class="top-avatar">M</div></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">TEAM ORGANIZATION STUDIO</div><h1>우리 팀의 역할을 한눈에</h1><p>사람과 업무를 연결하고, 함께 일하는 방식을 정리하세요.</p></div><div class="actions"><button class="btn" data-action="import">${icon('upload')}불러오기</button><button class="btn" data-action="export">${icon('download')}JSON 저장</button><button class="btn primary" data-action="print">${icon('print')}인쇄 / PDF</button></div></div><div class="stats"><button class="stat" data-action="view" data-value="table"><div><div class="stat-label">함께하는 구성원</div><div class="stat-value">${d.members.length}<small>/ 50명</small></div></div><div class="stat-icon">${icon('users')}</div></button><button class="stat" data-action="stat-filter" data-value="all"><div><div class="stat-label">전체 업무</div><div class="stat-value">${d.tasks.length}<small>개 업무</small></div></div><div class="stat-icon">${icon('task')}</div></button><button class="stat orange" data-action="stat-filter" data-value="unassigned"><div><div class="stat-label">담당자를 기다리는 업무</div><div class="stat-value">${un}<small>개 미배정</small></div></div><div class="stat-icon">${icon('inbox')}</div></button><button class="stat" data-action="stat-filter" data-value="shared"><div><div class="stat-label">함께 맡은 업무</div><div class="stat-value">${shared}<small>개 공동 담당</small></div></div><div class="stat-icon">${icon('share')}</div></button></div><section class="workspace"><div class="workspace-toolbar"><div class="tabs">${[['org','org','조직도'],['table','table','업무분장표'],['board','grid','업무 보드']].map(([v,i,l])=>`<button class="tab ${view===v?'active':''}" data-action="view" data-value="${v}">${icon(i)}${l}</button>`).join('')}${view==='history'?'<span class="tab active">변경 기록</span>':''}</div><div class="actions"><div class="search search-wide">${icon('search')}<input id="global-search" aria-label="구성원 및 업무 검색" placeholder="이름, 업무 검색" value="${esc(globalSearch)}"></div><button class="icon-button" data-action="undo" ${!undo.length?'disabled':''} title="실행 취소 (⌘/Ctrl Z)" aria-label="실행 취소">${icon('undo')}</button><button class="btn" data-action="member-new">${icon('plus')}구성원 추가</button></div></div>${view==='org'?orgView():view==='table'?tableView():view==='history'?historyView():boardView()}</section><div class="footnotes"><span>${icon('info')}공동 업무는 주담당을 지정하거나, 주담당 없이 함께 배정할 수 있습니다. 업무를 클릭해 역할을 정리하세요.</span><span><select id="department-picker" aria-label="부서 선택" style="font-size:10px;padding:4px;border-color:#e1e6d8;max-width:130px">${options(state.departments.map(d=>[d.id,d.name]),d.id)}</select>${icon('folder')}${d.effectiveDate?'시행일':'자료 기준'} ${esc(d.effectiveDate||d.reference?.dateText||'미설정')} <button data-action="dept-edit" style="color:#74905c;font-size:10px">수정</button><button class="btn ghost" data-action="dept-new" style="padding:0 5px;font-size:10px">부서 추가</button></span></div></div></main>`;requestAnimationFrame(fitGraph);}
function fitGraph(){
 const tree=$('.tree'),shell=$('.graph-shell'),vp=$('.graph-viewport');
 if(!tree||!shell||!vp)return;
 const cards=[...tree.querySelectorAll('.person-card')],heights=new Map();
 cards.forEach(card=>card.style.minHeight='');
 cards.forEach(card=>heights.set(card.dataset.depth,Math.max(heights.get(card.dataset.depth)||0,card.offsetHeight)));
 cards.forEach(card=>card.style.minHeight=heights.get(card.dataset.depth)+'px');
 if(autoFit)zoom=Math.min(1,Math.max(.25,(vp.clientWidth-32)/Math.max(1,tree.offsetWidth)));
 tree.style.transform=`scale(${zoom})`;shell.style.width=tree.offsetWidth*zoom+'px';shell.style.height=tree.offsetHeight*zoom+'px';$('#zoom-label').textContent=Math.round(zoom*100)+'%';
}
function closeModal(){const r=$('#modal-root');r.innerHTML='';document.body.style.overflow='';if(modalFocus?.isConnected)modalFocus.focus();}
function modal(title,subtitle,body,footer='',wide=false){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close" aria-label="닫기">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>{const el=$('.modal input:not([type=checkbox]),.modal textarea,.modal select')||$('.modal button');el?.focus();},50);}
const cancelBtn='<button type="button" class="btn" data-action="close">취소</button>';
function options(items,selected){return items.map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('');}
function taskModal(id){const d=dept(),t=d.tasks.find(t=>t.id===id)||{id:'',title:'',code:d.tasks.length<26?String.fromCharCode(65+d.tasks.length):String(d.tasks.length+1),category:'공통업무',weight:1,priority:'보통',owners:[],notes:''};modal(t.id?'업무 편집':'새 업무 추가','담당자, 업무 범위와 난이도를 함께 정리하세요.',`<form id="task-form" data-id="${esc(t.id)}"><div class="modal-body"><div class="field"><label for="t-title">업무명 *</label><input id="t-title" name="title" value="${esc(t.title)}" maxlength="120" required placeholder="예: 연간 사업계획 수립"></div><div class="form-row"><div class="field"><label for="t-code">업무 코드</label><input id="t-code" name="code" value="${esc(t.code)}" maxlength="16" placeholder="예: A"></div><div class="field"><label for="t-category">업무 분류</label><input id="t-category" name="category" list="categories" value="${esc(t.category)}" maxlength="50"><datalist id="categories">${[...new Set(d.tasks.map(t=>t.category))].map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist></div></div><div class="form-row"><div class="field"><label for="t-weight">난이도 · 업무량 계산에 반영</label><select id="t-weight" name="weight">${options([['1','1 · 가벼움'],['2','2 · 보통'],['3','3 · 높음']],String(t.weight))}</select></div><div class="field"><label for="t-priority">중요도</label><select id="t-priority" name="priority">${options(['낮음','보통','높음'].map(x=>[x,x]),t.priority)}</select></div></div><div class="field"><label for="t-primary">주담당</label><select id="t-primary" name="primary"><option value="">주담당 미지정</option>${options(d.members.map(m=>[m.id,`${m.name} · ${m.role}`]),primaryOwner(t))}</select><small>주담당을 비워 두고 아래에서 여러 명을 선택하면 동등한 공동 담당으로 저장됩니다. 담당자를 아무도 선택하지 않으면 미배정입니다.</small></div><div class="field"><label>함께 맡는 담당자 (복수 선택)</label><div class="checkbox-grid">${d.members.map(m=>`<label class="check-person"><input type="checkbox" name="collaborator" value="${esc(m.id)}" ${t.owners.filter(x=>x!==primaryOwner(t)).includes(m.id)?'checked':''}>${esc(m.name)} <small>${esc(m.role)}</small></label>`).join('')||'<small>먼저 구성원을 추가하세요.</small>'}</div></div><div class="field"><label for="t-unit">업무 소속 팀·파트</label><select id="t-unit" name="unitId"><option value="">미지정</option>${options((d.units||[]).filter(u=>u.type!=='external').map(u=>[u.id,unitPath(d,u.id)]),t.unitId)}</select></div><div class="field"><label for="t-notes">업무 범위 · 공동 담당 시 역할 구분</label><textarea id="t-notes" name="notes" maxlength="3000" placeholder="예: 주담당은 계획 수립, 협업 담당은 자료 검토를 맡습니다.">${esc(t.notes)}</textarea></div><div id="form-error" class="error-text" role="alert"></div></div><div class="modal-footer">${t.id?`<button type="button" class="btn danger" style="margin-right:auto" data-action="task-delete" data-id="${esc(t.id)}">${icon('trash')}삭제</button>`:''}${cancelBtn}<button class="btn primary" type="submit">${icon('check')}업무 저장</button></div></form>`);}
function memberModal(id){const d=dept(),m=d.members.find(m=>m.id===id)||{id:'',name:'',role:'팀원',team:'',parentId:d.members.find(m=>m.role==='팀장')?.id||d.members[0]?.id||null};if(!m.id&&d.members.length>=MAX_MEMBERS){toast('한 부서는 최대 50명까지 추가할 수 있습니다.',true);return;}const descendants=new Set(m.id?[m.id]:[]);let n;do{n=descendants.size;d.members.forEach(x=>{if(descendants.has(x.parentId))descendants.add(x.id);});}while(n!==descendants.size);modal(m.id?'구성원 정보 수정':'구성원 추가',m.id?'이름을 변경해도 연결된 업무와 조직 관계가 유지됩니다.':`현재 ${d.members.length}명 · 최대 50명까지 함께할 수 있어요.`,`<form id="member-form" data-id="${esc(m.id)}"><div class="modal-body"><div class="field"><label for="m-name">이름 *</label><input name="name" id="m-name" maxlength="40" required value="${esc(m.name)}" placeholder="이름을 입력하세요"></div><div class="form-row"><div class="field"><label for="m-role">직책 *</label><input name="role" id="m-role" list="roles" maxlength="30" required value="${esc(m.role)}"><datalist id="roles">${ROLES.map(x=>`<option value="${x}"></option>`).join('')}</datalist></div><div class="field"><label for="m-team">소속 팀</label><input name="team" id="m-team" maxlength="60" value="${esc(m.team)}" placeholder="예: 기획운영팀"></div></div><div class="form-row"><div class="field"><label for="m-grade">직급</label><input id="m-grade" name="grade" maxlength="30" list="grades" value="${esc(m.grade||'')}" placeholder="예: 부장, 차장, 과장, 대리"><datalist id="grades">${['교수','부장','차장','과장','대리','직원'].map(x=>`<option value="${x}"></option>`).join('')}</datalist></div><div class="field"><label for="m-employment">고용·인력 구분</label><input id="m-employment" name="employment" maxlength="30" list="employments" value="${esc(m.employment||'')}" placeholder="미표기"><datalist id="employments">${['교원','정규직','계약직','상담연구원','미표기'].map(x=>`<option value="${x}"></option>`).join('')}</datalist></div></div><div class="field"><label for="m-unit">소속 팀·파트</label><select id="m-unit" name="unitId"><option value="">부서 직속 / 미지정</option>${options((d.units||[]).filter(u=>u.type!=='external').map(u=>[u.id,unitPath(d,u.id)]),m.unitId)}</select><small>직급만으로 상하 관계를 정하지 않습니다. 실제 소속과 보고 대상을 각각 지정하세요.</small></div><div class="field"><label for="m-parent">보고 대상</label><select name="parent" id="m-parent"><option value="">최상위 구성원</option>${options(d.members.filter(x=>!descendants.has(x.id)).map(x=>[x.id,`${x.name} · ${x.role}`]),m.parentId)}</select><small>직책과 보고 대상은 자유롭게 바꿀 수 있습니다. 순환 관계는 자동으로 방지합니다.</small></div>${m.id?'<div class="info-box">후임자로 교체하려면 구성원 상세의 <b>인수인계 / 교체</b>를 사용하세요. 업무를 유지하고 교체 내역을 기록합니다.</div>':`<div class="info-box">여러 명을 한 번에 입력하려면 <button type="button" data-action="bulk-members" style="text-decoration:underline">이름 일괄 입력</button>을 이용하세요.</div>`}<div id="form-error" class="error-text" role="alert"></div></div><div class="modal-footer">${m.id?`<button type="button" class="btn danger" data-action="member-delete" data-id="${esc(m.id)}" style="margin-right:auto">삭제</button>`:''}${cancelBtn}<button class="btn primary" type="submit">구성원 저장</button></div></form>`);}
function personModal(id){const m=dept().members.find(m=>m.id===id);if(!m)return;const tasks=dept().tasks.filter(t=>t.owners.includes(id)),parent=dept().members.find(x=>x.id===m.parentId);modal('구성원 상세','역할과 담당 업무를 확인하고 인수인계를 준비하세요.',`<div class="modal-body"><div class="detail-header">${avatar(m)}<div><h3>${esc(m.name)}</h3><p>${esc([m.role,m.grade].filter(Boolean).join(' · '))}${(m.unitId||m.team)?' · '+esc(m.unitId?unitPath(dept(),m.unitId):m.team):''}${parent?' · 보고 대상 '+esc(parent.name):' · 최상위 구성원'}</p></div><button class="btn" style="margin-left:auto" data-action="member-edit" data-id="${esc(id)}">${icon('edit')}수정</button></div><div class="info-box">담당 업무 <b>${tasks.length}건</b> · 주담당 ${tasks.filter(t=>primaryOwner(t)===id).length}건 · 협업·공동 ${tasks.filter(t=>primaryOwner(t)!==id).length}건 · 참고 업무량 ${workload(dept(),id).toFixed(1)}점</div><div class="section-label">담당 업무</div><div class="detail-tasks">${tasks.map(t=>`${taskCard(t)}<div style="font-size:10px;color:#9ca68f;margin:-2px 0 10px 10px">${ownerRole(t,id)}${t.owners.length>1?' · 함께하는 사람 '+esc(t.owners.filter(x=>x!==id).map(x=>dept().members.find(m=>m.id===x)?.name).join(', ')):''}</div>`).join('')||'<div class="empty">아직 배정된 업무가 없어요.<br>업무 보관함에서 이 구성원에게 업무를 배정하세요.</div>'}</div></div>`,`<button class="btn" data-action="handover" data-id="${esc(id)}">${icon('users')}인수인계 / 교체</button><button class="btn primary" data-action="close">확인</button>`);}
function handoverModal(id){const m=dept().members.find(m=>m.id===id);modal('인수인계 / 담당자 교체','기존 업무와 보고 관계를 유지하면서 후임자로 교체합니다.',`<form id="handover-form" data-id="${esc(id)}"><div class="modal-body"><div class="info-box"><b>${esc(m.name)} · ${esc(m.role)}</b>의 업무 ${taskCount(m)}건이 후임자에게 그대로 연결됩니다. 공동 업무에서 맡은 역할도 유지됩니다.</div><div class="field"><label for="next-name">후임자 이름 *</label><input name="name" id="next-name" required maxlength="40" placeholder="새 담당자 이름"></div><div id="form-error" class="error-text" role="alert"></div></div><div class="modal-footer">${cancelBtn}<button class="btn primary" type="submit">교체하고 업무 인계</button></div></form>`);}
function deptModal(edit=false){if(!edit&&state.departments.length>=30)return toast('최대 30개 부서까지 만들 수 있습니다.',true);const d=edit?dept():{name:'',description:'',effectiveDate:new Date().toLocaleDateString('sv-SE')};modal(edit?'부서 정보':'새 부서 만들기',edit?'업무분장표의 기준 정보와 시행일을 관리합니다.':'이름을 입력하면 직책과 보고 관계를 자동으로 구성합니다.',`<form id="dept-form" data-edit="${edit}"><div class="modal-body"><div class="field"><label for="d-name">부서명 *</label><input name="name" id="d-name" maxlength="60" required value="${esc(d.name)}" placeholder="예: 경영지원처"></div><div class="field"><label for="d-description">부서 설명</label><input id="d-description" name="description" maxlength="200" value="${esc(d.description)}" placeholder="부서의 주요 역할을 적어 주세요"></div><div class="field"><label for="d-date">시행일 *</label><input name="date" id="d-date" type="date" required value="${esc(d.effectiveDate||'')}"></div>${!edit?'<div class="field"><label for="d-names">구성원 이름 (선택 · 최대 50명)</label><textarea name="names" id="d-names" placeholder="김민준, 이서연, 박도윤&#10;이름은 쉼표 또는 줄바꿈으로 구분해 주세요."></textarea><small>처장 → 부처장 → 팀장 → 선임팀원 → 팀원 순으로 구성합니다. 생성 후 자유롭게 수정할 수 있어요.</small></div>':''}<div id="form-error" class="error-text" role="alert"></div></div><div class="modal-footer">${edit&&state.departments.length>1?'<button type="button" class="btn danger" data-action="dept-delete" style="margin-right:auto">부서 삭제</button>':''}${cancelBtn}<button class="btn primary" type="submit">${edit?'저장':'부서 만들기'}</button></div></form>`);}
function bulkModal(){modal('구성원 이름 일괄 입력',`현재 ${dept().members.length}명 · ${MAX_MEMBERS-dept().members.length}명 추가 가능`,`<form id="bulk-form"><div class="modal-body"><div class="field"><label for="bulk-names">이름 *</label><textarea id="bulk-names" name="names" required placeholder="김민준, 이서연, 박도윤&#10;쉼표 또는 줄바꿈으로 구분해 주세요."></textarea><small>${dept().members.length?'기존 구성원을 유지하고 팀원으로 추가합니다. 보고 대상은 나중에 변경할 수 있어요.':'입력 순서대로 직책과 보고 관계를 자동 구성합니다.'}</small></div><div id="form-error" class="error-text" role="alert"></div></div><div class="modal-footer">${cancelBtn}<button class="btn primary" type="submit">일괄 추가</button></div></form>`);}
function confirmModal(title,body,action,id=''){modal(title,'변경 후에는 실행 취소로 되돌릴 수 있습니다.',`<div class="modal-body"><div class="info-box warning">${body}</div></div>`,`${cancelBtn}<button class="btn danger" data-action="${action}" data-id="${esc(id)}">삭제</button>`);}
function exportJSON(){const blob=new Blob([exportState(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`MACH_업무분장_${new Date().toLocaleDateString('sv-SE')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('전체 부서의 JSON 백업을 저장했습니다.');}
function helpModal(){modal('업무분장, 이렇게 시작하세요','예시 데이터는 가상의 구성원 10명과 A–Z 업무 26개로 구성되어 있습니다.',`<div class="modal-body"><ol class="help-list"><li><strong>우리 부서 만들기</strong><br>‘부서 추가’에서 이름을 한 번에 입력하세요. 직책과 보고 관계가 자동으로 만들어집니다. 부서별 최대 50명입니다.</li><li><strong>사람과 업무 연결하기</strong><br>업무를 사람 카드에 끌어다 놓으세요. 조직도 상단 ‘업무내용 표시’를 켜면 모든 담당 업무와 메모가 보입니다. 표시 여부는 이 브라우저에 기억됩니다. ‘담당 이동’은 기존 담당자를 교체하고, ‘공동 담당 추가’는 기존 담당자를 유지합니다. 모바일에서는 업무를 눌러 담당자를 선택하세요.</li><li><strong>보고 관계 바꾸기</strong><br>사람 카드의 손잡이를 다른 사람에게 끌어 놓거나 구성원 정보의 보고 대상을 수정하세요. 직책 이름과 보고 관계는 별도로 관리됩니다.</li><li><strong>인사 변경도 간편하게</strong><br>구성원 상세 → ‘인수인계 / 교체’에서 후임자 이름을 입력하면 업무를 그대로 인계합니다. ‘삭제’하면 남은 공동 담당자가 주담당을 승계하고, 담당자가 없어진 업무는 미배정됩니다.</li><li><strong>백업하고 한 장으로 인쇄하기</strong><br>JSON에는 모든 부서와 변경 기록이 포함됩니다. 인쇄는 가로·세로, A4·A3, 업무분장표·조직도를 지원합니다. 한 장 맞춤은 내용이 많을수록 글자가 작아집니다.</li></ol><div class="info-box">이 버전은 <b>현재 브라우저에 자동 저장</b>합니다. 다른 기기와의 실시간 동기화 기능은 없습니다. 주기적으로 JSON을 저장하세요. MACH 통합 시 별도 서버 저장·로그인 연동을 추가할 수 있습니다.</div><div class="actions"><button class="btn" data-action="dept-new">${icon('plus')}우리 부서 만들기</button><button class="btn" data-action="export">${icon('download')}JSON 저장</button></div></div>`,`<button class="btn primary" data-action="close">시작하기</button>`,true);}

function printModal(){modal('한 장에 담는 업무분장표','전체 구성원과 업무를 포함합니다. 화면 검색 조건은 인쇄에 적용되지 않습니다.',`<div class="modal-body"><div class="print-options"><div class="field"><label for="print-kind">인쇄 내용</label><select id="print-kind"><option value="table">업무분장표 (권장)</option><option value="org">보고 관계 조직도</option><option value="units" ${dept().units?.length?'selected':''}>팀·파트별 업무분장표</option></select></div><div class="field"><label for="print-size">용지</label><select id="print-size"><option value="A4">A4</option><option value="A3">A3 · 많은 인원에 권장</option></select></div><div class="field"><label for="print-orientation">방향</label><select id="print-orientation"><option value="landscape">가로형</option><option value="portrait">세로형</option></select></div><div class="field"><label for="print-fit">배치</label><select id="print-fit"><option value="one">한 장에 모두 맞춤</option><option value="pages">읽기 좋은 크기 · 여러 장 허용</option></select></div></div><label class="check-person"><input id="print-notes" type="checkbox">업무별 상세 메모 포함</label><div class="paper-preview"><div class="paper" id="paper-preview"><b>${esc(dept().name)} 업무분장표</b><p>${dept().members.length}명 · ${dept().tasks.length}개 업무 · ${esc(dept().effectiveDate)}</p><div class="paper-lines"></div></div></div><div class="info-box" style="margin-top:16px;margin-bottom:0">인쇄 창에서도 선택한 용지와 방향을 확인하세요. 배율은 100%, 머리글·바닥글은 끄기를 권장합니다. PDF 저장은 인쇄 창의 ‘PDF로 저장’을 선택하세요.</div><div id="print-live-preview" class="print-live-preview" hidden></div><div id="print-status" class="error-text" role="status" style="padding-top:10px"></div></div>`,`<button class="btn" data-action="close">닫기</button><button class="btn" data-action="print-preview">미리보기</button><button class="btn primary" data-action="do-print">${icon('print')}인쇄 / PDF 저장</button>`,true);}
function taskPrint(t,notes){return `<span class="task-print"><b>${esc(t.code)}</b> ${esc(t.title)}${t.owners.length>1?' [공동]':''}${notes&&t.notes?` <span style="color:#687661">(${esc(t.notes)})</span>`:''}</span>`;}
async function doPrint(previewOnly=false){const d=dept(),size=$('#print-size').value,orientation=$('#print-orientation').value,one=$('#print-fit').value==='one',kind=$('#print-kind').value,notes=$('#print-notes').checked;const dims=size==='A4'?[210,297]:[297,420];const w=(orientation==='landscape'?dims[1]:dims[0])-20,h=(orientation==='landscape'?dims[0]:dims[1])-20;let style=$('#page-style');if(!style){style=document.createElement('style');style.id='page-style';document.head.append(style);}style.textContent=`@page {size:${size} ${orientation};margin:10mm;} @media print {#print-root {width:${w}mm;} .print-doc{break-inside:${one?'avoid':'auto'};page-break-inside:${one?'avoid':'auto'}} .print-doc tr{break-inside:avoid;page-break-inside:avoid} .print-doc thead{display:table-header-group} }`;
 const printTree=p=>d.members.filter(m=>m.parentId===p).map(m=>`<li><div class="print-node"><b>${esc(m.name)} · ${esc(m.role)}</b>${esc(m.team)}${d.tasks.filter(t=>t.owners.includes(m.id)).map(t=>`<p>${primaryOwner(t)===m.id?'●':'○'} ${esc(t.code)} ${esc(t.title)}${notes&&t.notes?' — '+esc(t.notes):''}</p>`).join('')||'<p>담당 업무 없음</p>'}</div>${d.members.some(x=>x.parentId===m.id)?`<ul>${printTree(m.id)}</ul>`:''}</li>`).join('');
 const un=d.tasks.filter(t=>!t.owners.length);$('#print-root').innerHTML=`<article class="print-doc"><h1>${esc(d.name)} ${kind!=='org'?'업무분장표':'조직도'}</h1><div class="report-meta"><span>${esc(d.description||'')} · 구성원 ${d.members.length}명 · 업무 ${d.tasks.length}개 · 공동 ${d.tasks.filter(t=>t.owners.length>1).length}개 · 미배정 ${un.length}개</span><span>${d.effectiveDate?'시행일':'자료 기준'} ${esc(d.effectiveDate||d.reference?.dateText||'미설정')}</span></div>${kind==='units'?unitPrint(d,notes):kind==='table'?`<table><thead><tr><th style="width:10%">구성원</th><th style="width:15%">직책 / 소속 / 보고 대상</th><th style="width:43%">주담당 업무</th><th style="width:27%">협업·공동 업무</th><th style="width:5%">건수</th></tr></thead><tbody>${d.members.map(m=>`<tr><td><b>${esc(m.name)}</b></td><td>${esc([m.role,m.grade].filter(Boolean).join(' / '))}${(m.unitId||m.team)?' / '+esc(m.unitId?unitPath(dept(),m.unitId):m.team):''}<br><small>보고: ${esc(d.members.find(x=>x.id===m.parentId)?.name||'—')}</small></td><td>${d.tasks.filter(t=>primaryOwner(t)===m.id).map(t=>taskPrint(t,notes)).join('')||'—'}</td><td>${d.tasks.filter(t=>t.owners.includes(m.id)&&primaryOwner(t)!==m.id).map(t=>taskPrint(t,notes)).join('')||'—'}</td><td>${taskCount(m)}</td></tr>`).join('')}</tbody></table>`:`<div class="print-tree"><ul>${printTree(null)}</ul></div>`}${un.length?`<div class="unassigned-print"><b>미배정 업무 (${un.length})</b> · ${un.map(t=>taskPrint(t,notes)).join('')}</div>`:''}<div class="print-footer">${kind!=='org'?'공동 업무는 해당 담당자에게 각각 표기됩니다. 주담당 미지정은 원본의 공동 역할을 유지한 것입니다.':'● 주담당 · ○ 협업·공동 담당'} 동일 업무가 여러 명에게 표시될 수 있으며 총 업무 수는 중복을 제외합니다.<br>MACH 업무분장 스튜디오 · 출력일 ${new Date().toLocaleDateString('ko-KR')}</div></article>`;
 const root=$('#print-root'),doc=root.querySelector('.print-doc');root.style.cssText=`display:block;position:fixed;left:-100000px;top:0;width:${w}mm;`;doc.style.width=w+'mm';await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));if(kind==='org'){const tw=doc.querySelector('.print-tree>ul').scrollWidth;doc.style.width=Math.max(w*96/25.4,tw+10)+'px';}
 const factor=one?Math.min(1,(w*96/25.4-4)/doc.scrollWidth,(h*96/25.4-10)/doc.scrollHeight):Math.min(1,(w*96/25.4-4)/doc.scrollWidth);doc.style.zoom=String(factor);root.style.cssText='';$('#print-status').textContent=factor<.6?`한 장에 맞추기 위해 ${Math.round(factor*100)}%로 축소합니다. 글씨가 작으면 A3 또는 여러 장 배치를 선택하세요.`:'';if(previewOnly){const host=$('#print-live-preview');host.hidden=false;host.innerHTML=doc.outerHTML;$('#paper-preview').parentElement.hidden=true;return;}window.print();}

let pendingImport=null;
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('파일은 5MB 이하여야 합니다.');pendingImport=validateState(JSON.parse(await file.text()));const ds=pendingImport.departments;modal('JSON 백업 불러오기','기존 작업을 유지하면서 자료를 별도 부서로 추가할 수 있습니다.',`<div class="modal-body"><div class="info-box"><b>${esc(file.name)}</b><br>부서 ${ds.length}개 · 구성원 ${ds.reduce((s,d)=>s+d.members.length,0)}명 · 업무 ${ds.reduce((s,d)=>s+d.tasks.length,0)}개<br>${ds.map(d=>esc(d.name)).join(', ')}</div><div class="field"><label for="import-mode">불러오기 방식</label><select id="import-mode"><option value="add">새 부서로 추가 · 현재 부서 유지</option><option value="replace">전체 워크스페이스 교체</option></select><small>기본값은 별도 부서로 추가입니다. 전체 교체를 선택하면 기존 부서가 파일 내용으로 바뀝니다. 실행 취소로 되돌릴 수 있습니다.</small></div></div>`,`<button class="btn" data-action="export">현재 자료 백업</button>${cancelBtn}<button class="btn primary" data-action="confirm-import">불러오기</button>`);}catch(err){toast('불러오기 실패: '+err.message,true);}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,v=b.dataset.value;
 switch(a){case'units-from-teams':change('기존 소속명으로 팀 생성',()=>{dept().units??=[];[...new Set(dept().members.map(m=>m.team).filter(Boolean))].forEach(name=>{const u={id:uid(),name,type:'team',parentId:null,managerId:null};dept().units.push(u);dept().members.filter(m=>m.team===name).forEach(m=>m.unitId=u.id);});});break;case'units-manage':unitsModal();break;case'unit-new':unitModal();break;case'unit-edit':unitModal(id);break;case'unit-delete':confirmModal('팀·파트를 삭제할까요?','구성원과 업무는 그대로 유지하고 상위 팀·파트로 옮깁니다.','confirm-unit-delete',id);break;case'confirm-unit-delete':unitFilter='';change('팀·파트 삭제',()=>removeUnit(dept(),id));closeModal();break;case'review':reviewModal();break;case'toggle-inbox':inboxOpen=!inboxOpen;render();break;case'toggle-org-tasks':showOrgTasks=!showOrgTasks;try{localStorage.setItem(VIEW_KEY,String(showOrgTasks));}catch{}render();requestAnimationFrame(()=>$('#org-tasks-toggle')?.focus({preventScroll:true}));break;case'view':view=v;search='';category='';if(v==='board')taskFilter='all';render();break;case'stat-filter':taskFilter=v;view='board';search='';globalSearch='';category='';render();break;case'task-filter':taskFilter=v;render();break;case'drop-mode':dropMode=v;render();break;case'person':personModal(id);break;case'member-edit':memberModal(id);break;case'member-new':memberModal();break;case'task-new':taskModal();break;case'task-edit':taskModal(id);break;case'close':closeModal();break;case'dept-new':deptModal();break;case'dept-edit':deptModal(true);break;case'dept-switch':unitFilter='';orgLayout='auto';state.activeDepartmentId=id;search='';globalSearch='';category='';autoFit=true;save();render();break;case'bulk-members':bulkModal();break;case'handover':handoverModal(id);break;case'export':exportJSON();break;case'import':$('#import-file').click();break;case'help':helpModal();break;case'print':printModal();break;case'print-preview':doPrint(true).catch(e=>toast(e.message,true));break;case'do-print':doPrint().catch(e=>toast(e.message,true));break;case'undo':rewind();break;case'zoom-in':zoom=Math.min(1.6,zoom+.1);autoFit=false;fitGraph();break;case'zoom-out':zoom=Math.max(.2,zoom-.1);autoFit=false;fitGraph();break;case'zoom-fit':autoFit=true;fitGraph();break;
 case'member-delete':{const m=dept().members.find(x=>x.id===id);confirmModal('구성원을 삭제할까요?',`<b>${esc(m.name)}</b>을 삭제합니다. 단독 업무는 미배정으로 이동하고, 공동 업무는 남은 담당자가 이어받습니다. 하위 구성원은 상위 보고 대상에 연결됩니다.`,'confirm-member-delete',id);break;}
 case'confirm-member-delete':{const name=dept().members.find(m=>m.id===id)?.name;change(`${name} 구성원 삭제`,()=>removeMember(dept(),id));closeModal();toast('구성원을 삭제했습니다. 업무는 보존됩니다.');break;}
 case'task-delete':confirmModal('업무를 삭제할까요?','모든 담당자에게서 이 업무가 제거됩니다.','confirm-task-delete',id);break;
 case'confirm-task-delete':{const t=dept().tasks.find(t=>t.id===id);change(`업무 삭제: ${t.title}`,()=>{dept().tasks=dept().tasks.filter(t=>t.id!==id);});closeModal();break;}
 case'dept-delete':confirmModal('부서를 삭제할까요?',`<b>${esc(dept().name)}</b>의 구성원 ${dept().members.length}명과 업무 ${dept().tasks.length}개가 함께 삭제됩니다. 필요한 자료는 먼저 JSON으로 저장하세요.`,'confirm-dept-delete');break;
 case'confirm-dept-delete':change(`${dept().name} 부서 삭제`,()=>{state.departments=state.departments.filter(d=>d.id!==state.activeDepartmentId);state.activeDepartmentId=state.departments[0].id;});closeModal();break;
 case'confirm-import':if(pendingImport){try{localStorage.setItem(BACKUP,JSON.stringify(state));}catch{}const add=$('#import-mode')?.value!=='replace';try{change(add?'JSON 부서 추가':'JSON 워크스페이스 교체',()=>{state=add?mergeWorkspace(state,pendingImport):clone(pendingImport);});}catch(e){toast(e.message,true);break;}unitFilter='';orgLayout='auto';view='org';render();pendingImport=null;closeModal();toast('백업 파일을 불러왔습니다.');}break;
 }
});
function parseNames(raw,available=MAX_MEMBERS){const names=raw.split(/[\n,，]+/).map(x=>x.trim()).filter(Boolean);if(names.length>available)throw Error(`최대 ${available}명까지 입력할 수 있습니다.`);if(names.some(n=>n.length>40))throw Error('이름은 40자 이내로 입력해 주세요.');return names;}
document.addEventListener('submit',e=>{if(!e.target.matches('.modal form'))return;e.preventDefault();const f=e.target,fd=new FormData(f),id=f.dataset.id,trim=n=>String(fd.get(n)||'').trim();try{
 if(f.id==='unit-form'){saveUnitForm(f,fd);}
 else if(f.id==='task-form'){const owners=[...new Set([trim('primary'),...fd.getAll('collaborator')].filter(Boolean))];if(!trim('title'))throw Error('업무명을 입력하세요.');if(!id&&dept().tasks.length>=500)throw Error('한 부서는 최대 500개 업무를 관리할 수 있습니다.');const data={id:id||uid(),title:trim('title'),code:trim('code'),category:trim('category')||'일반',weight:Number(fd.get('weight')),priority:trim('priority'),notes:trim('notes'),owners,primaryOwnerId:trim('primary')||null,unitId:trim('unitId')||null};change(`${id?'업무 수정':'업무 추가'}: ${data.title}`,()=>{const ix=dept().tasks.findIndex(t=>t.id===id);if(ix>=0)dept().tasks[ix]=data;else dept().tasks.push(data);});toast('업무를 저장했습니다.');}
 else if(f.id==='member-form'){if(!trim('name')||!trim('role'))throw Error('이름과 직책을 입력하세요.');const data={name:trim('name'),role:trim('role'),team:trim('team'),grade:trim('grade'),employment:trim('employment'),unitId:trim('unitId')||null};change(`${id?'구성원 수정':'구성원 추가'}: ${data.name}`,()=>{if(id){moveMember(dept(),id,trim('parent')||null);Object.assign(dept().members.find(m=>m.id===id),data);}else{if(dept().members.length>=MAX_MEMBERS)throw Error('최대 50명까지 추가할 수 있습니다.');dept().members.push({...data,id:uid(),parentId:trim('parent')||null,color:dept().members.length%6});}});}
 else if(f.id==='handover-form'){if(!trim('name'))throw Error('후임자 이름을 입력하세요.');const old=dept().members.find(m=>m.id===id);if(old.name===trim('name'))throw Error('현재 담당자와 다른 후임자 이름을 입력하세요.');change(`${old.name} → ${trim('name')} 인수인계 (${taskCount(old)}개 업무 유지)`,()=>{old.name=trim('name');});toast('담당자를 교체하고 업무를 인계했습니다.');}
 else if(f.id==='dept-form'){if(!trim('name'))throw Error('부서명을 입력하세요.');const edit=f.dataset.edit==='true',names=edit?[]:parseNames(trim('names'));change(`${edit?'부서 정보 수정':'부서 생성'}: ${trim('name')}`,()=>{if(edit)Object.assign(dept(),{name:trim('name'),description:trim('description'),effectiveDate:trim('date')});else{const d={id:uid(),name:trim('name'),description:trim('description'),effectiveDate:trim('date'),members:hierarchy(names),tasks:[]};state.departments.push(d);state.activeDepartmentId=d.id;}});view='org';globalSearch='';search='';autoFit=true;render();}
 else if(f.id==='bulk-form'){const names=parseNames(trim('names'),MAX_MEMBERS-dept().members.length);if(!names.length)throw Error('추가할 이름을 입력하세요.');change(`구성원 ${names.length}명 일괄 추가`,()=>{if(!dept().members.length)dept().members=hierarchy(names);else names.forEach(name=>dept().members.push({id:uid(),name,role:'팀원',team:'',parentId:dept().members.find(m=>m.role==='팀장')?.id||dept().members[0].id,color:dept().members.length%6}));});}
 closeModal();}catch(err){const out=$('#form-error');if(out)out.textContent=err.message;else toast(err.message,true);}});

let searchTimer;
document.addEventListener('input',e=>{if(e.target.id==='task-search'||e.target.id==='global-search'){const id=e.target.id,val=e.target.value,pos=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(id==='task-search')search=val;else{globalSearch=val;search='';}render();const el=$('#'+id);el?.focus();el?.setSelectionRange(pos,pos);},120);}});
document.addEventListener('change',e=>{if(e.target.id==='org-layout'){orgLayout=e.target.value;render();}if(e.target.id==='unit-filter'){unitFilter=e.target.value;render();}if(e.target.id==='department-picker'){state.activeDepartmentId=e.target.value;unitFilter='';orgLayout='auto';search='';globalSearch='';category='';autoFit=true;save();render();}if(e.target.id==='category-filter'){category=e.target.value;render();}if(e.target.id==='print-orientation')$('#paper-preview').classList.toggle('portrait',e.target.value==='portrait');if(e.target.id==='print-kind')$('#paper-preview b').textContent=dept().name+(e.target.value==='org'?' 조직도':' 업무분장표');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,textarea,select')&&!$('.modal')){e.preventDefault();rewind(e.shiftKey);return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('div[data-action][role=button]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&$('.modal')){const focusables=$$('.modal button:not(:disabled),.modal input,.modal select,.modal textarea,.modal [tabindex="0"]');const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-drag-task]'),m=e.target.closest('[data-drag-member]');if(!t&&!m)return;drag={type:t?'task':'member',id:t?t.dataset.dragTask:m.dataset.dragMember};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',JSON.stringify(drag));document.body.classList.add('drag-'+drag.type);(t||m).classList.add('dragging');});
document.addEventListener('dragover',e=>{if(!drag)return;const target=e.target.closest(drag.type==='task'?'[data-drop-person],[data-drop-unassign]':'[data-drop-person],[data-drop-root]');if(target){e.preventDefault();e.dataTransfer.dropEffect='move';$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));target.classList.add('drop-target');}});
function clearDrag(){$$('.drop-target,.dragging').forEach(x=>x.classList.remove('drop-target','dragging'));document.body.classList.remove('drag-task','drag-member');drag=null;}
document.addEventListener('dragend',clearDrag);
document.addEventListener('drop',e=>{if(!drag)return;const target=e.target.closest(drag.type==='task'?'[data-drop-person],[data-drop-unassign]':'[data-drop-person],[data-drop-root]');if(!target){clearDrag();return;}e.preventDefault();const {type,id}=drag,memberId=target.dataset.dropPerson||null;clearDrag();if(type==='task'){const t=dept().tasks.find(t=>t.id===id),m=dept().members.find(m=>m.id===memberId);if(!t)return;change(`${t.title}: ${m?m.name+(dropMode==='share'?' 공동 담당 추가':' 담당 배정'):'미배정으로 이동'}`,()=>assignTask(dept(),id,memberId,dropMode));toast(m?`${m.name}님에게 ${dropMode==='share'?'공동 배정':'배정'}했습니다.`:'미배정 업무로 이동했습니다.');}else{const m=dept().members.find(m=>m.id===id);if(!m)return;try{const copy=clone(dept());moveMember(copy,id,memberId);change(`${m.name} 보고 대상 변경`,()=>moveMember(dept(),id,memberId));}catch(e){toast(e.message,true);}}});
window.addEventListener('resize',()=>requestAnimationFrame(fitGraph));
document.fonts.ready.then(()=>requestAnimationFrame(fitGraph));
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue&&e.newValue!==JSON.stringify(state))toast('다른 창에서 자료가 변경되었습니다. 현재 작업을 JSON으로 저장한 뒤 새로고침해 주세요.',true);});
render();if(loadWarning)setTimeout(()=>toast(loadWarning,true),500);else {try {if(!localStorage.getItem(KEY))save();}catch{storageOK=false;render();}}

function unitDescendants(id){const set=new Set([id]);let n;do{n=set.size;(dept().units||[]).forEach(u=>{if(set.has(u.parentId))set.add(u.id);});}while(n!==set.size);return set;}
function memberMatches(m){return !globalSearch||[m.name,m.role,m.grade,m.employment,unitPath(dept(),m.unitId),m.team,...dept().tasks.filter(t=>t.owners.includes(m.id)).map(t=>t.title)].join(' ').toLowerCase().includes(globalSearch.toLowerCase());}
function unitSection(u){const d=dept(),members=d.members.filter(m=>m.unitId===u.id&&memberMatches(m)),children=(d.units||[]).filter(x=>x.parentId===u.id),all=unitDescendants(u.id),count=d.members.filter(m=>all.has(m.unitId)).length;return `<section class="unit-section ${u.type==='external'?'external-unit':''}"><header class="unit-heading"><div><span class="unit-type">${u.type==='team'?'팀':u.type==='external'?'별도 조직':'업무 파트'}</span><h3>${esc(u.name)}</h3>${u.managerId?`<small class="unit-manager">총괄 ${esc(d.members.find(m=>m.id===u.managerId)?.name||'')}</small>`:''}</div><span class="unit-count">${u.type==='external'?`별도 ${u.headcount??'미확인'}명`:count+'명'}</span><button class="icon-button" data-action="unit-edit" data-id="${esc(u.id)}" aria-label="${esc(u.name)} 수정">${icon('edit')}</button></header>${u.type==='external'?`<div class="external-detail"><strong>${esc(u.contact||'대표 미지정')}</strong><p>부서 구성원 수와 별도로 집계합니다.</p>${showOrgTasks?(u.scope||[]).map(t=>`<div class="external-task">${esc(t)}</div>`).join(''):''}${u.notes?`<p>${esc(u.notes)}</p>`:''}</div>`:`${members.length?`<div class="unit-members">${members.map(m=>personCard(m,0)).join('')}</div>`:!children.length?'<p class="unit-empty">소속 구성원이 없습니다.</p>':''}${children.length?`<div class="unit-subgroups">${children.map(unitSection).join('')}</div>`:''}`}</section>`;}
function unitView(){const d=dept(),units=d.units||[],roots=unitFilter?units.filter(u=>u.id===unitFilter):units.filter(u=>!u.parentId),loose=unitFilter?[]:d.members.filter(m=>!m.unitId&&memberMatches(m));return `<div class="unit-filterbar"><div class="actions"><select id="unit-filter" aria-label="팀·파트 필터"><option value="">전체 팀·파트</option>${options(units.map(u=>[u.id,unitPath(d,u.id)]),unitFilter)}</select><span>${units.filter(u=>u.type==='team').length}개 팀 · ${units.filter(u=>u.type==='part').length}개 파트</span></div><button class="btn ${d.reference?.notes?.length?'review-button':''}" data-action="review">${icon('info')}검토사항${d.reference?.notes?.length?' '+d.reference.notes.length:''}</button></div>${d.reference?`<div class="reference-strip">자료 기준 ${esc(d.reference.dateText||'미표기')} · ${esc(d.reference.label)}${d.reference.notes.length?' · 확인할 내용이 있습니다.':''}</div>`:''}<div class="unit-view" id="organization-tree">${loose.length?`<section class="direct-unit"><h3>부서 직속 / 소속 미지정</h3><div class="unit-members">${loose.map(m=>personCard(m,0)).join('')}</div></section>`:''}<div class="unit-columns ${roots.length===1?'single-unit':''}">${roots.map(unitSection).join('')}</div>${!units.length?`<div class="empty"><strong>실제 팀과 업무 파트로 묶어 보세요</strong><p>직급 순서와 별개로 소속 단위를 만들 수 있습니다.</p><div class="actions" style="justify-content:center"><button class="btn primary" data-action="unit-new">팀·파트 추가</button>${d.members.some(m=>m.team)?'<button class="btn" data-action="units-from-teams">기존 소속명으로 묶기</button>':''}</div></div>`:''}</div>`;}
function unitsModal(){modal('팀·파트와 별도 조직','직급과 보고 관계를 바꾸지 않고 실제 업무 단위를 구성합니다.',`<div class="modal-body"><div class="info-box">팀 아래에 방문학생·입학·관리 같은 업무 파트를 둘 수 있습니다. 센터처럼 구성원 명단이 없는 조직은 대표와 별도 인원, 업무 범위로 관리합니다.</div>${(dept().units||[]).map(u=>`<div class="unit-manage-row"><div><b>${esc(unitPath(dept(),u.id))}</b><small>${u.type==='external'?'별도 조직 · '+(u.headcount??'미확인')+'명':dept().members.filter(m=>m.unitId===u.id).length+'명 직접 소속'}</small></div><button class="btn" data-action="unit-edit" data-id="${esc(u.id)}">수정</button></div>`).join('')||'<p class="empty">아직 등록된 팀·파트가 없습니다.</p>'}</div>`,`<button class="btn" data-action="close">닫기</button><button class="btn primary" data-action="unit-new">${icon('plus')}팀·파트 추가</button>`,true);}
function unitModal(id){const d=dept(),u=(d.units||[]).find(u=>u.id===id)||{id:'',name:'',type:'part',parentId:null,managerId:null,headcount:null,contact:'',scope:[],notes:''},excluded=id?unitDescendants(id):new Set();modal(u.id?'팀·파트 수정':'팀·파트 추가','업무 단위와 담당 총괄, 별도 조직 정보를 설정하세요.',`<form id="unit-form" data-id="${esc(u.id)}"><div class="modal-body"><div class="form-row"><div class="field"><label for="u-name">단위명 *</label><input name="name" id="u-name" required maxlength="60" value="${esc(u.name)}" placeholder="예: 국제교류팀, 방문학생"></div><div class="field"><label for="u-type">구분</label><select name="type" id="u-type">${options([['team','팀'],['part','업무 파트'],['external','센터·별도 조직']],u.type)}</select></div></div><div class="field"><label for="u-parent">상위 팀·파트</label><select name="parentId" id="u-parent"><option value="">부서 직속</option>${options((d.units||[]).filter(x=>!excluded.has(x.id)&&x.type!=='external').map(x=>[x.id,unitPath(d,x.id)]),u.parentId)}</select></div><div class="field"><label for="u-manager">총괄 담당 (선택)</label><select name="managerId" id="u-manager"><option value="">미지정</option>${options(d.members.map(m=>[m.id,m.name+' · '+m.role]),u.managerId)}</select><small>이 항목만으로 구성원의 보고 대상을 바꾸지는 않습니다.</small></div><details ${u.type==='external'?'open':''}><summary>센터·별도 조직 정보</summary><div class="form-row" style="margin-top:12px"><div class="field"><label for="u-contact">대표·연락 담당</label><input name="contact" id="u-contact" maxlength="100" value="${esc(u.contact)}" placeholder="예: 김○○ 외 7명"></div><div class="field"><label for="u-headcount">별도 인원 수</label><input name="headcount" id="u-headcount" type="number" min="0" max="10000" value="${u.headcount??''}"></div></div><div class="field"><label for="u-scope">업무 범위 (한 줄에 하나)</label><textarea name="scope" id="u-scope">${esc((u.scope||[]).join('\n'))}</textarea></div></details><div class="field"><label for="u-notes">비고</label><textarea name="notes" id="u-notes" maxlength="3000">${esc(u.notes)}</textarea></div><div id="form-error" class="error-text" role="alert"></div></div><div class="modal-footer">${u.id?`<button type="button" class="btn danger" style="margin-right:auto" data-action="unit-delete" data-id="${esc(u.id)}">삭제</button>`:''}${cancelBtn}<button type="submit" class="btn primary">저장</button></div></form>`,true);}
function saveUnitForm(f,fd){const v=k=>String(fd.get(k)||'').trim(),id=f.dataset.id;if(!v('name'))throw Error('팀·파트 이름을 입력해 주세요.');const data={id:id||uid(),name:v('name'),type:v('type'),parentId:v('parentId')||null,managerId:v('managerId')||null,contact:v('contact'),headcount:v('headcount')===''?null:Number(v('headcount')),scope:v('scope').split('\n').map(s=>s.trim()).filter(Boolean),notes:v('notes')};if(data.type==='external'&&dept().members.some(m=>m.unitId===id))throw Error('소속 구성원을 다른 파트로 옮긴 뒤 별도 조직으로 바꿔 주세요.');change(`팀·파트 ${id?'수정':'추가'}: ${data.name}`,()=>{dept().units??=[];const ix=dept().units.findIndex(u=>u.id===id);if(ix>=0)dept().units[ix]=data;else dept().units.push(data);});orgLayout='units';render();}
function reviewModal(){const d=dept(),un=d.tasks.filter(t=>!t.owners.length),joint=d.tasks.filter(t=>t.owners.length>1&&!primaryOwner(t)),externals=(d.units||[]).filter(u=>u.type==='external');modal('자료 검토와 배정 현황','원본에서 확정할 수 없는 내용은 임의로 채우지 않고 남깁니다.',`<div class="modal-body">${d.reference?`<div class="info-box"><b>${esc(d.reference.label)}</b><br>자료 기준: ${esc(d.reference.dateText||'미표기')}</div><ol class="review-notes">${d.reference.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ol>`:'<div class="info-box">현재 부서에는 별도의 원본 검토사항이 없습니다.</div>'}<div class="section-label">현재 배정 현황</div><div class="review-metrics"><p>이름이 등록된 구성원 <b>${d.members.length}명</b></p><p>센터·별도 조직 <b>${externals.length}개 / ${externals.reduce((s,u)=>s+(u.headcount||0),0)}명</b></p><p>미배정 업무 <b>${un.length}개</b></p><p>주담당 미지정 공동 업무 <b>${joint.length}개</b></p></div><p style="font-size:11px;color:#8a987c;line-height:1.9">공동 담당은 오류가 아닙니다. 책임자를 명확히 정해야 하는 업무만 주담당을 지정하세요. 원본의 인원 합계와 실제 명단이 다르면 명단을 우선 보존하고 합계를 확인하세요.</p></div>`,`<button class="btn primary" data-action="close">확인</button>`,true);}
function unitPrint(d,notes){const units=d.units||[],ordered=[],walk=(parent=null)=>units.filter(u=>u.parentId===parent).forEach(u=>{ordered.push(u);walk(u.id);});walk();const groups=[{name:'부서 직속 / 소속 미지정',members:d.members.filter(m=>!m.unitId)},...ordered.filter(u=>u.type!=='external').map(u=>({name:unitPath(d,u.id),members:d.members.filter(m=>m.unitId===u.id)}))].filter(g=>g.members.length);return `<table><thead><tr><th style="width:13%">구성원</th><th style="width:18%">직책 · 직급 / 인력 구분</th><th style="width:32%">주담당 업무</th><th style="width:32%">협업·공동 업무</th><th style="width:5%">건수</th></tr></thead><tbody>${groups.map(g=>`<tr class="print-unit-heading"><th colspan="5">${esc(g.name)} (${g.members.length}명)</th></tr>${g.members.map(m=>`<tr><td><b>${esc(m.name)}</b></td><td>${esc([m.role,m.grade].filter(Boolean).join(' · '))}<br>${esc(m.employment||'인력 구분 미표기')}</td><td>${d.tasks.filter(t=>primaryOwner(t)===m.id).map(t=>taskPrint(t,notes)).join('')||'—'}</td><td>${d.tasks.filter(t=>t.owners.includes(m.id)&&primaryOwner(t)!==m.id).map(t=>taskPrint(t,notes)+(!primaryOwner(t)?'<small> (주담당 미지정)</small>':'')).join('')||'—'}</td><td>${d.tasks.filter(t=>t.owners.includes(m.id)).length}</td></tr>`).join('')}`).join('')}</tbody></table>${ordered.filter(u=>u.type==='external').map(u=>`<div class="unassigned-print"><b>${esc(unitPath(d,u.id))}</b> · 별도 ${u.headcount??'미확인'}명 · ${esc(u.contact)}<br>${(u.scope||[]).map(esc).join(' / ')}${u.notes?'<br>'+esc(u.notes):''}</div>`).join('')}${d.reference?`<div class="print-footer">자료 기준 ${esc(d.reference.dateText)} · ${esc(d.reference.label)}${d.reference.notes.length?'<br>검토사항: '+d.reference.notes.map(esc).join(' / '):''}</div>`:''}`;}
